import { Link } from 'react-router-dom';
import { useContext, useState } from 'react';
import AuthContext from '../context/AuthContext';
import Logo from '../assets/logo.svg';

function Navbar() {
  const { user, logout } = useContext(AuthContext);
  const [open, setOpen] = useState(false);

  return (
    <header className="navbar">
      <div className="container nav-inner">
        <div className="brand" style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <img src={Logo} alt="logo" style={{ width: 40, height: 40 }} />
          <Link to="/" className="brand-link">Automated Resume Screening</Link>
        </div>

        <nav className={`nav-links ${open ? 'open' : ''}`}>
          <Link to="/upload" className="nav-link" onClick={() => setOpen(false)}>Analysis Engine</Link>
          <Link to="/dashboard" className="nav-link" onClick={() => setOpen(false)}>My Intelligence</Link>
          <Link to="/jobs" className="nav-link" onClick={() => setOpen(false)}>Opportunities</Link>
          <Link to="/history" className="nav-link" onClick={() => setOpen(false)}>Archive</Link>
          {!user ? (
            <>
              <Link to="/login" className="nav-link" onClick={() => setOpen(false)}>Login</Link>
              <Link to="/signup" className="nav-link nav-cta" onClick={() => setOpen(false)}>Start Free</Link>
            </>
          ) : (
            <>
              <span className="nav-user font-black text-[11px] uppercase tracking-widest muted">
                {user.name || user.email}
              </span>
              <button
                onClick={() => { logout(); setOpen(false); }}
                className="btn btn-ghost"
                style={{ padding: '8px 16px', fontSize: '12px' }}
              >
                Logout
              </button>
            </>
          )}
        </nav>

        <button
          className={`hamburger ${open ? 'is-active' : ''}`}
          aria-label="Open menu"
          aria-expanded={open}
          onClick={() => setOpen(!open)}
        >
          <span className="bar" />
          <span className="bar" />
          <span className="bar" />
        </button>
      </div>

      {/* Mobile menu overlay */}
      <div className={`mobile-menu ${open ? 'show' : ''}`} onClick={() => setOpen(false)}>
        <div className="mobile-inner" onClick={(e) => e.stopPropagation()}>
          <Link to="/upload" className="mobile-link" onClick={() => setOpen(false)}>Upload</Link>
          <Link to="/dashboard" className="mobile-link" onClick={() => setOpen(false)}>Dashboard</Link>
          <Link to="/jobs" className="mobile-link" onClick={() => setOpen(false)}>Jobs</Link>
          <Link to="/history" className="mobile-link" onClick={() => setOpen(false)}>History</Link>
          {!user ? (
            <>
              <Link to="/login" className="mobile-link" onClick={() => setOpen(false)}>Login</Link>
              <Link to="/signup" className="mobile-link mobile-cta" onClick={() => setOpen(false)}>Signup</Link>
            </>
          ) : (
            <>
              <div className="mobile-user">{user.name || user.email}</div>
              <button onClick={() => { logout(); setOpen(false); }} className="mobile-logout">Logout</button>
            </>
          )}
        </div>
      </div>
    </header>
  );
}

export default Navbar;
